//! Actual generated bytes must match the single registry declaration set.
#![allow(
    clippy::expect_used,
    reason = "regeneration assertions identify exact stale paths"
)]
mod common;

#[test]
fn registry_generated_files_match_current_declarations() {
    let root = common::workspace_root();
    let registry = pse_schema::registry().expect("registry");
    for language in pse_codegen::codegen::Language::ALL {
        let tree = pse_codegen::codegen::generate(registry, language).expect("generator");
        assert!(!tree.files.is_empty());
        for (path, expected) in tree.files {
            let actual = std::fs::read(root.join(&path)).expect("generated file exists");
            let first_difference = actual
                .iter()
                .zip(&expected)
                .position(|(actual, expected)| actual != expected)
                .unwrap_or(actual.len().min(expected.len()));
            assert!(
                actual == expected,
                "{} requires just codegen: first difference at byte {first_difference}, actual {} bytes, expected {} bytes",
                path.display(),
                actual.len(),
                expected.len()
            );
        }
    }
}
